parameters.jsCode:
// Extract phone, text, and (optional) location pin / voice audio id from Meta WhatsApp Cloud API webhook.
const body = $input.item.json.body ?? $input.item.json;

if (body['hub.mode'] === 'subscribe') {
  return [{ json: { phone: null, messageText: null, isVerification: true, challenge: body['hub.challenge'] } }];
}

const entry = body.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;

if (value?.statuses && !value?.messages) {
  return [];
}

const message = value?.messages?.[0];
const contact = value?.contacts?.[0];
if (!message) {
  return [];
}

const phone = message.from;
const messageType = message.type;
let messageText = '';
let latitude = null;
let longitude = null;
let locationText = null;
let mediaId = '';

if (messageType === 'text') {
  messageText = message.text?.body || '';
} else if (messageType === 'location') {
  latitude = message.location?.latitude;
  longitude = message.location?.longitude;
  locationText = message.location?.name || message.location?.address || '';
  messageText = '[location]';
} else if (messageType === 'interactive') {
  const br = message.interactive?.button_reply;
  const lr = message.interactive?.list_reply;
  messageText = br?.id || lr?.id || br?.title || lr?.title || '';
} else if (messageType === 'audio') {
  // Voice note / audio — capture the media id; the transcription branch fills messageText.
  mediaId = message.audio?.id || '';
  messageText = '';
} else {
  messageText = '[unsupported: ' + messageType + ']';
}

return [{
  json: {
    phone: phone,
    messageText: messageText,
    hasPin: messageType === 'location',
    pinLat: latitude,
    pinLng: longitude,
    locationText: locationText,
    messageType: messageType,
    mediaId: mediaId,
    messageId: message.id,
    timestamp: message.timestamp,
    contactName: contact?.profile?.name || ''
  }
}];

