const sess = (
  $('Save_Updated_Conversation').all().length > 0
    ? $('Save_Updated_Conversation').first().json
    : $('Save_New_Conversation').first().json
) || {};


function tryParseJsonString(value) {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch (e) { return value; }
}

function pushCandidates(value, out) {
  value = tryParseJsonString(value);
  if (value === null || value === undefined) return;

  if (Array.isArray(value)) {
    for (const v of value) pushCandidates(v, out);
    return;
  }

  if (typeof value !== 'object') return;

  // n8n HTTP Request can return either the JSON body directly, or a wrapper with body/data.
  if (Array.isArray(value.body) || Array.isArray(value.data) || Array.isArray(value.results)) {
    pushCandidates(value.body || value.data || value.results, out);
    return;
  }

  if (typeof value.body === 'string') {
    pushCandidates(value.body, out);
    return;
  }

  out.push(value);
}

const candidates = [];
for (const item of $input.all()) pushCandidates(item.json, candidates);

const errorItem = candidates.find(x => x && x.error);
const getPlaceId = (x) => x?.placeID ?? x?.placeId ?? x?.placeid ?? x?.place_id ?? '';
const valid = candidates.find(x => String(getPlaceId(x) || '').trim().length > 0);

if (!valid) {
  const err = errorItem?.error?.message || errorItem?.message || '';
  return [{ json: {
    ...sess,
    _resolved: false,
    _errorMessage: err
      ? `Autocab could not search that address: ${err}`
      : "Sorry, I couldn't find that pickup address. Please type a fuller address or postcode.",
  }}];
}

return [{ json: {
  ...sess,
  _resolved: true,
  _placeId: String(getPlaceId(valid)).trim(),
  _topAddressText: valid.address || valid.fullAddress || valid.text || '',
  _lookupRaw: valid,
}}];

const sess = $('Pick_First_Pickup_Place').first().json;

function tryParseJsonString(value) {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch (e) { return value; }
}

function unwrapAddress(value) {
  value = tryParseJsonString(value);
  if (Array.isArray(value)) value = value[0] || {};
  if (value && typeof value === 'object') {
    if (typeof value.body === 'string') value.body = tryParseJsonString(value.body);
    if (value.body && typeof value.body === 'object') value = value.body;
    if (value.data && typeof value.data === 'object') value = value.data;
    if (value.address && value.address.coordinate) value = value.address;
  }
  return value || {};
}

function isValidAddress(addr) {
  const lat = addr?.coordinate?.latitude;
  const lng = addr?.coordinate?.longitude;
  return !!addr
    && !addr.error
    && !!addr.text
    && lat !== undefined && lat !== null
    && lng !== undefined && lng !== null
    && (addr.zoneId !== undefined || !!addr.zone);
}

const addr = unwrapAddress($input.first()?.json || {});

if (!isValidAddress(addr)) {
  const msg = addr?.error?.message || addr?.message || "Autocab could not turn that pickup into a full address. Please type a fuller pickup address or postcode.";
  return [{ json: {
    phone: sess.phone,
    step: 'awaiting_pickup',
    lastActiveAt: new Date().toISOString(),
    pickupAddressJson: '',
    pickupText: sess.pickupText,
    resolvedText: '',
    _resolved: false,
    _errorMessage: msg,
  }}];
}

const isAirport = sess.intent === 'airport_pickup';
return [{ json: {
  phone: sess.phone,
  step: isAirport ? 'airport_pickup_choose_buffer' : 'awaiting_pickup_confirm',
  intent: sess.intent || '',         // pass intent through so downstream IF can branch
  lastActiveAt: new Date().toISOString(),
  pickupAddressJson: JSON.stringify(addr),
  pickupText: addr.text || sess.pickupText,
  resolvedText: addr.text || sess.pickupText,
  _resolved: true,
}}];

