parameters.jsCode:
const sess = (
  $('Save_Updated_Conversation').all().length > 0
    ? $('Save_Updated_Conversation').first().json
    : $('Save_New_Conversation').first().json
) || {};


function tryParse(value) {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return value; }
}

function unwrap(value) {
  value = tryParse(value);
  if (Array.isArray(value)) value = value[0] || {};
  if (value?.body) value = tryParse(value.body);
  if (value?.data) value = value.data;
  if (value?.address?.coordinate) value = value.address;
  return value || {};
}

function joinParts(parts) {
  return parts
    .map(v => String(v || '').trim())
    .filter(Boolean)
    .filter((v, i, arr) => arr.findIndex(x => x.toLowerCase() === v.toLowerCase()) === i)
    .join(', ');
}

function isPlaceholderText(text) {
  const t = String(text || '').trim().toLowerCase();
  return !t
    || t === 'pinned location'
    || t === 'whatsapp pin'
    || t === 'whatsapp location pin'
    || t === 'location pin'
    || /^-?\d+(\.\d+)?\s*,\s*-?\d+(\.\d+)?$/.test(t);
}

function buildCleanAddressText(addr, fallbackLabel) {
  const houseStreet = joinParts([addr.house, addr.street]);
  const lineFromParts = joinParts([
    houseStreet,
    addr.town,
    addr.postCode
  ]);

  const extraCandidate = [
    addr.fullAddress,
    addr.formattedAddress,
    addr.displayAddress,
    addr.address,
    addr.description
  ].find(v => String(v || '').trim() && !isPlaceholderText(v));

  const textCandidate = !isPlaceholderText(addr.text) ? String(addr.text).trim() : '';

  if (textCandidate) return textCandidate;
  if (extraCandidate) return String(extraCandidate).trim();
  if (lineFromParts) return lineFromParts;

  const zoneName = addr.zone?.name || addr.zoneName || '';
  const zoneDescriptor = addr.zone?.descriptor || '';
  const zoneText = joinParts([zoneName ? `near ${zoneName}` : '', zoneDescriptor ? `zone ${zoneDescriptor}` : '']);

  return zoneText
    ? `Approximate ${fallbackLabel} from WhatsApp pin, ${zoneText}`
    : `Approximate ${fallbackLabel} from WhatsApp location pin`;
}

function isValidAddress(addr) {
  const lat = addr?.coordinate?.latitude;
  const lng = addr?.coordinate?.longitude;
  return !!addr
    && !addr.error
    && lat !== undefined && lat !== null
    && lng !== undefined && lng !== null
    && (addr.zoneId !== undefined || !!addr.zone);
}

const addr = unwrap($input.first()?.json || {});
const lat = addr?.coordinate?.latitude;
const lng = addr?.coordinate?.longitude;

if (!isValidAddress(addr)) {
  return [{
    json: {
      ...sess,
      _resolved: false,
      _errorMessage: "Couldn't reverse-geocode your pin in Autocab. Please type the pickup address."
    }
  }];
}

const cleanText = buildCleanAddressText(addr, 'pickup address');
const cleanedAddr = {
  ...addr,
  text: cleanText,
  note: joinParts([
    addr.note,
    `Customer sent a WhatsApp location pin. Exact coordinates: ${lat}, ${lng}. Address is approximate and should be checked if unclear.`
  ])
};

// Keep the exact pin coordinates for Autocab pricing/dispatch, but show a useful address text to the office and customer.
cleanedAddr.coordinate = {
  ...(addr.coordinate || {}),
  latitude: lat,
  longitude: lng,
  isEmpty: false
};

return [{
  json: {
    phone: sess.phone,
    step: 'awaiting_pickup_confirm',
    lastActiveAt: new Date().toISOString(),
    pickupAddressJson: JSON.stringify(cleanedAddr),
    pickupText: cleanText,
    resolvedText: cleanText,
    pinLat: lat,
    pinLng: lng,
    _resolved: true,
  }
}];

