// Build a NewBookingRequest payload using fully-resolved Autocab Address objects.
// The quote endpoint uses the same booking request structure as Create Booking.
// Capabilities are resolved from the live Autocab /capabilities response.
const s = $('Save_Updated_Conversation').first().json;

function tryParseJsonString(value) {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch (e) { return value; }
}

function unwrapAddress(value) {
  value = tryParseJsonString(value);
  if (Array.isArray(value)) value = value[0] || {};
  if (value && typeof value === 'object') {
    if (typeof value.body === 'string') value.body = tryParseJsonString(value.body);
    if (value.body && typeof value.body === 'object') value = value.body;
    if (value.data && typeof value.data === 'object') value = value.data;
    if (value.address && value.address.coordinate) value = value.address;
  }
  return value || {};
}

function isValidAddress(addr) {
  const lat = addr?.coordinate?.latitude;
  const lng = addr?.coordinate?.longitude;
  return !!addr
    && !addr.error
    && !addr.message
    && addr.text
    && lat !== undefined && lat !== null
    && lng !== undefined && lng !== null
    && (addr.zoneId !== undefined || !!addr.zone);
}

function normaliseText(value) {
  return String(value ?? '').toLowerCase().replace(/[^a-z0-9]+/g, '');
}

function getCapabilityListFromInput() {
  const items = $input.all().map(item => item.json);
  const caps = [];
  for (const item of items) {
    if (Array.isArray(item)) caps.push(...item);
    else if (Array.isArray(item?.body)) caps.push(...item.body);
    else if (Array.isArray(item?.data)) caps.push(...item.data);
    else if (Array.isArray(item?.capabilities)) caps.push(...item.capabilities);
    else if (item && typeof item === 'object' && item.id !== undefined && item.name !== undefined) caps.push(item);
  }
  return caps.filter(c => c && c.id !== undefined);
}

function findCapabilityId(kind, caps) {
  const enabledVehicleCaps = caps.filter(c => c.enabled !== false && String(c.requirement || '').toLowerCase() === 'vehicle');

  if (kind === 'estate') {
    const hit = enabledVehicleCaps.find(c => {
      const name = normaliseText(c.name);
      const shortCode = String(c.shortCode ?? '').trim().toLowerCase();
      return shortCode === 'e'
        || name === 'estate'
        || name.includes('estate')
        || name.includes('wagon')
        || name.includes('stationwagon');
    });
    return hit ? Number(hit.id) : null;
  }

  if (kind === 'six') {
    const hit = enabledVehicleCaps.find(c => {
      const name = normaliseText(c.name);
      const shortCode = String(c.shortCode ?? '').trim().toLowerCase();
      return shortCode === '6'
        || name === '6seater'
        || name === 'sixseater'
        || name.includes('6seat')
        || name.includes('sixseat')
        || name.includes('mpv');
    });
    return hit ? Number(hit.id) : null;
  }

  if (kind === 'eight') {
    const hit = enabledVehicleCaps.find(c => {
      const name = normaliseText(c.name);
      const shortCode = String(c.shortCode ?? '').trim().toLowerCase();
      return shortCode === '8'
        || name === '8seater'
        || name === 'eightseater'
        || name.includes('8seat')
        || name.includes('eightseat')
        || name.includes('minibus')
        || name.includes('peoplecarrier');
    });
    return hit ? Number(hit.id) : null;
  }

  if (kind === 'wheelchair') {
    const hit = enabledVehicleCaps.find(c => {
      const name = normaliseText(c.name);
      const shortCode = String(c.shortCode ?? '').trim().toLowerCase();
      return shortCode === 'w'
        || name.includes('wheelchair')
        || name.includes('accessible')
        || name.includes('wav');
    });
    return hit ? Number(hit.id) : null;
  }

  return null;
}

function resolveCapabilityIds(rawValue, vehicleType, passengerCount) {
  let requested = [];
  try { requested = JSON.parse(rawValue || '[]'); } catch (e) { requested = []; }
  if (!Array.isArray(requested)) requested = [];

  const ids = requested
    .filter(c => typeof c === 'number' || /^\d+$/.test(String(c)))
    .map(c => Number(c));

  const names = requested
    .filter(c => !(typeof c === 'number' || /^\d+$/.test(String(c))))
    .map(c => normaliseText(c));

  const needsEstate = vehicleType === 'estate' || names.some(n => n.includes('estate') || n.includes('wagon') || n.includes('stationwagon'));
  const needsSixSeater = vehicleType === 'mpv' || passengerCount === '5-6' || names.some(n => n.includes('6seat') || n.includes('sixseat') || n.includes('mpv'));
  const needsEightSeater = vehicleType === '8seater' || passengerCount === '7+' || names.some(n => n.includes('8seat') || n.includes('eightseat') || n.includes('minibus') || n.includes('peoplecarrier'));
  const needsWheelchair = vehicleType === 'wheelchair' || names.some(n => n.includes('wheelchair') || n.includes('accessible') || n.includes('wav'));

  const availableCapabilities = getCapabilityListFromInput();

  if (needsEstate) {
    const estateId = findCapabilityId('estate', availableCapabilities);
    if (estateId) ids.push(estateId);
  }

  if (needsSixSeater) {
    const sixId = findCapabilityId('six', availableCapabilities);
    if (!sixId && !ids.length) {
      return { error: 'Autocab 6 Seater capability was not found. Check /booking/v1/capabilities and make sure the 6 Seater vehicle capability is enabled.' };
    }
    if (sixId) ids.push(sixId);
  }

  if (needsEightSeater) {
    const eightId = findCapabilityId('eight', availableCapabilities);
    if (!eightId && !ids.length) {
      return { error: 'Autocab 8 Seater capability was not found. Check /booking/v1/capabilities and make sure the 8 Seater vehicle capability is enabled.' };
    }
    if (eightId) ids.push(eightId);
  }

  if (needsWheelchair) {
    const wheelchairId = findCapabilityId('wheelchair', availableCapabilities);
    if (wheelchairId) ids.push(wheelchairId);
  }

  return { ids: [...new Set(ids.filter(Number.isFinite))] };
}

const pickupAddr = unwrapAddress(s.pickupAddressJson || '{}');
const destAddr = unwrapAddress(s.destinationAddressJson || '{}');
// Last-resort airport coordinate fallback
// If pickup is the airport branch and the address didn't resolve, inject known coords.
let airport = {};
try { airport = s.airportJson ? JSON.parse(s.airportJson) : {}; } catch (e) {}
const AIRPORT_COORDS = {
  LHR: { lat: 51.4700, lng: -0.4543, zone: { id: 1, name: 'LHR', descriptor: 'Heathrow', mdtZoneId: 1 } },
  LGW: { lat: 51.1537, lng: -0.1821, zone: { id: 2, name: 'LGW', descriptor: 'Gatwick',  mdtZoneId: 2 } },
  STN: { lat: 51.8860, lng:  0.2389, zone: { id: 3, name: 'STN', descriptor: 'Stansted', mdtZoneId: 3 } },
  LTN: { lat: 51.8763, lng: -0.3717, zone: { id: 4, name: 'LTN', descriptor: 'Luton',    mdtZoneId: 4 } },
  LCY: { lat: 51.5048, lng:  0.0495, zone: { id: 5, name: 'LCY', descriptor: 'City',     mdtZoneId: 5 } }
};

if (s.intent === 'airport_pickup' && airport.code && !isValidAddress(pickupAddr)) {
  const coords = AIRPORT_COORDS[airport.code];
  if (coords) {
    pickupAddr = {
      source: 'Operator',
      id: -1,
      isCustom: false,
      text: pickupAddr.text || `${airport.name} – Terminal ${airport.terminal || ''}`.trim(),
      coordinate: { latitude: coords.lat, longitude: coords.lng, isEmpty: false },
      zone: coords.zone,
      zoneId: coords.zone.id,
      house: '',
      street: pickupAddr.text || airport.name || '',
      town: airport.name || '',
      postCode: '',
      bookingPriority: 0,
      note: `Flight ${airport.flightNumber}${airport.arrivalTerminal ? ' – Terminal ' + airport.arrivalTerminal : ''}`
    };
  }
}
if (!isValidAddress(pickupAddr) || !isValidAddress(destAddr)) {
  return [{ json: {
    _localError: !isValidAddress(pickupAddr)
      ? 'Pickup address has not been resolved by Autocab yet. Please reply 2 and enter a fuller pickup address or postcode.'
      : 'Destination address has not been resolved by Autocab yet. Please reply 2 and enter a fuller destination address or postcode.',
    session: s,
    phone: s.phone,
  }}];
}

const resolvedCaps = resolveCapabilityIds(s.capabilitiesJson, s.vehicleType, s.passengerCount);
if (resolvedCaps.error) {
  return [{ json: {
    _localError: resolvedCaps.error,
    session: s,
    phone: s.phone,
  }}];
}

function derivePassengers(vehicleType, passengerCount, rawCaps) {
  // Trust vehicleType FIRST — never let caps JSON override a known vehicle type
  if (vehicleType === '8seater')   return '8';
  if (vehicleType === 'mpv')       return '6';
  if (vehicleType === 'wheelchair') return '1';
  if (vehicleType === 'estate')    return '4';
  // Saloon: use actual passenger count if customer provided it
  if (passengerCount && /^\d+$/.test(String(passengerCount))) {
    const n = parseInt(passengerCount);
    if (n >= 1 && n <= 16) return String(n);
  }
  return '4';
}

const passengersStr = derivePassengers(s.vehicleType, s.passengerCount, s.capabilitiesJson);
const pickupDueTime    = s.pickupDueTime    || s.pickupDateTimeUtc || s.pickupDateTime || new Date().toISOString();
const pickupDueTimeUtc = s.pickupDueTimeUtc || s.pickupDateTimeUtc || pickupDueTime;

const payload = {
  capabilities: resolvedCaps.ids,
  companyId: 1,
  bookingSource: 'ThirdPartyOther',
  name: s.passengerName || '',
  passengers: passengersStr,
  telephoneNumber: s.phone,
  pickup: {
    address: pickupAddr,
    note: '',
    passengerDetailsIndex: null,
    type: 'Pickup',
  },
  destination: {
    address: destAddr,
    note: '',
    passengerDetailsIndex: null,
    type: 'Destination',
  },
  pickupDueTime,
pickupDueTimeUtc,
  hold: false,
};

return [{ json: payload }];

// Parse Autocab BookingQuote using documented fields: outward.price, outward.cost, outward.distance, outward.measurement, outward.time
let sess = {};
try { sess = $('Save_Updated_Conversation').first().json || {}; } catch (e) { sess = {}; }
const raw = $input.first().json || {};
if (raw.session) sess = { ...sess, ...raw.session };

// ---------- helpers ----------
function tryParse(v) {
  if (!v) return null;
  if (typeof v === 'object') return v;
  if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { return null; } }
  return null;
}
function fmtUk(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '';
  const date = d.toLocaleDateString('en-GB', { timeZone: 'Europe/London', day: '2-digit', month: 'short', year: 'numeric' });
  const time = d.toLocaleTimeString('en-GB', { timeZone: 'Europe/London', hour: '2-digit', minute: '2-digit', hour12: false });
  return `${date} at ${time}`;
}
function fmtTimeOnly(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '';
  return d.toLocaleTimeString('en-GB', { timeZone: 'Europe/London', hour: '2-digit', minute: '2-digit', hour12: false });
}

// ---------- error handling (unchanged) ----------
const extractEmbeddedError = (obj) => {
  if (obj?._localError) return [obj._localError];
  const direct = obj?.message || obj?.errorMessage;
  if (typeof direct === 'string' && direct.trim()) return [direct];
  const msg = obj?.error?.message;
  if (typeof msg !== 'string') return [];
  const jsonMatch = msg.match(/"(\{[\s\S]*\})"$/);
  if (!jsonMatch) return [msg];
  try {
    const parsed = JSON.parse(jsonMatch[1].replace(/\r/g, '').replace(/\n/g, ''));
    if (Array.isArray(parsed.errors)) {
      return parsed.errors.map(e => e.title || e.detail).filter(Boolean);
    }
  } catch (e) {}
  return [msg];
};

const q = (raw.error || raw._localError) ? { errors: extractEmbeddedError(raw) } : raw;
const outward = q.outward || {};
const errors = Array.isArray(q.errors) ? q.errors.map(e => typeof e === 'string' ? e : (e?.title || e?.detail || JSON.stringify(e))).filter(Boolean) : [];
const warnings = Array.isArray(q.warnings) ? q.warnings.map(w => typeof w === 'string' ? w : JSON.stringify(w)).filter(Boolean) : [];

const parseNumber = (value) => {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string') {
    const cleaned = value.replace(/[^0-9.-]/g, '');
    if (!cleaned) return null;
    const n = Number(cleaned);
    return Number.isFinite(n) ? n : null;
  }
  return null;
};
const parseDuration = (value) => {
  if (!value || typeof value !== 'string') return '';
  const m = value.match(/^(\d{1,2}):(\d{2})(?::(\d{2})(?:\.\d+)?)?$/);
  if (!m) return value;
  const totalMin = (parseInt(m[1], 10) * 60) + parseInt(m[2], 10);
  return totalMin > 0 ? `${totalMin} min` : '';
};

const price = parseNumber(outward.price) ?? parseNumber(outward.cost) ?? parseNumber(outward.bookingPrice) ?? parseNumber(outward.bookingCost);
const distance = parseNumber(outward.distance);
const measurement = outward.measurement || 'Miles';
const durationStr = parseDuration(outward.time || '');
const tariff = outward.tariff || '';

if (price === null && errors.length) {
  const msg = [
    'Sorry, I could not get a fare quote.',
    errors.join('; '),
    '',
    'Reply:',
    '2 - Change details',
    '3 - Cancel'
  ].join('\n');
  return [{ json: {
    phone: sess.phone,
    step: 'awaiting_quote_confirm',
    ok: false,
    quoteMessage: msg,
    _quoteMessage: msg,
    lastQuotePrice: '',
    lastQuoteEta: '',
    lastQuoteTariff: '',
  }}];
}

// ---------- Build the quote card ----------
const isAirport = sess.intent === 'airport_pickup';
const airport = tryParse(sess.airportJson) || {};
const flight = airport.flightObject || {};

const lines = [];

if (isAirport) {
  lines.push('✈️ Here is your airport pickup quote:');
  lines.push('');
  if (sess.passengerName) lines.push(`👤 Passenger: ${sess.passengerName}`);
  if (sess.phone)         lines.push(`📞 Contact: ${sess.phone}`);
  lines.push('');

  // Flight block
  const airlineLabel = flight.airline ? `${flight.airline}` : '';
  const flightNo     = airport.flightNumber || (flight.airlineCode && flight.flightNumber ? `${flight.airlineCode}${flight.flightNumber}` : '');
  if (flightNo)      lines.push(`✈️ Flight: ${flightNo}${airlineLabel ? ' (' + airlineLabel + ')' : ''}`);
  if (flight.departureAirport) {
    const depCode = flight.departureAirportCode ? ` (${flight.departureAirportCode})` : '';
    lines.push(`🛫 From: ${flight.departureAirport}${depCode}`);
  }
  if (airport.arrivalTimeUtc) {
    const termText = airport.arrivalTerminal ? ` – Terminal ${airport.arrivalTerminal}` : '';
    lines.push(`🛬 Arrives: ${fmtUk(airport.arrivalTimeUtc)}${termText}`);
  }
  if (airport.bufferMinutes) lines.push(`⏱️ Driver ready: ${airport.bufferMinutes} min after arrival`);
  if (airport.pickupAtUtc)   lines.push(`🕒 Pickup time: ${fmtUk(airport.pickupAtUtc)}`);
  lines.push('');
}
else {
  lines.push('Here is your quote:');
  lines.push('');
  if (sess.passengerName) lines.push(`👤 Passenger: ${sess.passengerName}`);
  if (sess.phone)         lines.push(`📞 Contact: ${sess.phone}`);
  if (sess.pickupTimeMode === 'asap') {
    lines.push(`🕒 Pickup: ASAP`);
  } else if (sess.pickupDateTime) {
    lines.push(`🕒 Pickup: ${fmtUk(sess.pickupDateTime)}`);
  }
  lines.push('');
}

// Common booking details
lines.push(`📍 Pickup: ${sess.pickupText || 'Not provided'}`);
lines.push(`🏁 Destination: ${sess.destinationText || 'Not provided'}`);
lines.push(`🚕 Vehicle: ${sess.vehicleType || 'Not provided'}`);
if (distance !== null) lines.push(`🛣️ Distance: ${distance.toFixed(1)} ${measurement}`);
if (durationStr)       lines.push(`⏳ Journey time: ${durationStr}`);
lines.push(`💷 Fare: ${price !== null ? `£${price.toFixed(2)}` : 'pending'}`);

if (warnings.length) {
  lines.push('');
  lines.push(`⚠️ Note: ${warnings.join('; ')}`);
}

const msg = lines.join('\n');
return [{ json: {
  phone: sess.phone,
  step: 'awaiting_quote_confirm',
  ok: price !== null,
  quoteMessage: msg,
  _quoteMessage: msg,
  lastQuotePrice: price !== null ? `£${price.toFixed(2)}` : '',
  lastQuoteEta: durationStr,
  lastQuoteTariff: tariff,
} }];

