parameters.jsCode:
// Merge incoming WhatsApp event with stored DB row, then advance the state machine.
const incoming = $('Extract_WhatsApp_Data').first().json;
const dbRow = $input.first().json || {};

// 30-minute stale timeout: if user's last activity was >30m ago, reset to welcome.
const STALE_MS = 30 * 60 * 1000;
const now = new Date();
const last = dbRow.lastActiveAt ? new Date(dbRow.lastActiveAt) : null;
const stale = last && !isNaN(last.getTime()) && (now - last) > STALE_MS;

const session = {
  phone: dbRow.phone || incoming.phone || '',
  step: stale ? 'welcome' : (dbRow.step || 'welcome'),
  intent: dbRow.intent || '',
  pickupText: dbRow.pickupText || '',
  destinationText: dbRow.destinationText || '',
  pickupAddressJson: dbRow.pickupAddressJson || '',
  destinationAddressJson: dbRow.destinationAddressJson || '',
  pickupTimeMode: dbRow.pickupTimeMode || '',
  pickupDateTime: dbRow.pickupDateTime || '',
  passengerCount: dbRow.passengerCount || '',
  vehicleType: dbRow.vehicleType || '',
  passengerName: dbRow.passengerName || '',
  capabilitiesJson: dbRow.capabilitiesJson || '[]',
  lastQuotePrice: dbRow.lastQuotePrice || '',
  lastQuoteEta: dbRow.lastQuoteEta || '',
  lastBookingId: dbRow.lastBookingId || '',
  status: dbRow.status || 'open',
  driverNote: dbRow.driverNote || '',
  noteNextStep: dbRow.noteNextStep || '',
  lastActiveAt: now.toISOString(),
  pinLat: incoming.pinLat,
  pinLng: incoming.pinLng,
  hasPin: !!incoming.hasPin,
};

// Rehydrate airport sub-state (handles string OR object OR missing)
if (dbRow.airportJson) {
  if (typeof dbRow.airportJson === 'string' && dbRow.airportJson.length > 0) {
    try { session.airport = JSON.parse(dbRow.airportJson); }
    catch (e) { session.airport = {}; }
  } else if (typeof dbRow.airportJson === 'object') {
    session.airport = dbRow.airportJson;
  } else {
    session.airport = {};
  }
} else {
  session.airport = {};
}
// ─── Rehydrate manage-booking sub-state ───
try { session.managedBookings = JSON.parse(dbRow.managedBookingsJson || '[]'); }
catch { session.managedBookings = []; }
session.selectedBookingId        = dbRow.selectedBookingId        || '';
session.selectedBookingIsCurrent = dbRow.selectedBookingIsCurrent || '';
session.managedBookingsJson      = dbRow.managedBookingsJson      || '';

const reply = (incoming.messageText || '').trim();   // ← exactly one of these
const lc = reply.toLowerCase();

// Hybrid intent parser - numbers OR keywords.
function matchIntent(s) {
  if (s === '1' || /\b(book|booking|cab|taxi|ride)\b/.test(s)) return 'book';
  if (s === '2' || /\b(quote|price|fare|cost|how much)\b/.test(s)) return 'quote';
  if (s === '3' || /\b(manage|change|cancel|update|existing)\b/.test(s)) return 'manage';
  return null;
}
function matchTimeMode(s) {
  if (s === '1' || /\b(asap|now|immediately|right now|right away)\b/.test(s)) return 'asap';
  if (s === '2' || /\b(later|schedule|book for|tonight|tomorrow)\b/.test(s)) return 'later';
  if (s === '3' || /\b(airport|flight|terminal|arriving|departure)\b/.test(s)) return 'airport';
  return null;
}
function matchPassengers(s) {
  if (s === '1' || /\b([1-4]|one|two|three|four)\s*(passenger|pax|people|person)?\b/.test(s)) return '1-4';
  if (s === '2' || /\b(5|6|five|six)\s*(passenger|pax|people)?\b/.test(s)) return '5-6';
  if (s === '3' || /\b([7-9]|7\+|seven|eight|nine|ten|10)\b/.test(s)) return '7+';
  return null;
}
function matchVehicle(s) {
  // This replaces the separate passenger-count question. The vehicle choice now decides
  // both the Autocab capability marker and the passenger count sent in the quote/booking payload.
  if (s === '1' || /\b(saloon|sedan|standard|car)\b/.test(s)) return { v: 'saloon', caps: [], passengers: '1-4' };
  if (s === '2' || /\b(estate|wagon|station)\b/.test(s)) return { v: 'estate', caps: ['Estate'], passengers: '1-4' };
  if (s === '3' || /\b(mpv|minivan|6\s*seat|six\s*seat|6\s*seater|six\s*seater)\b/.test(s)) return { v: 'mpv', caps: ['6 Seater'], passengers: '5-6' };
  if (s === '4' || /\b(8\s*seat|eight\s*seat|8\s*seater|eight\s*seater|minibus|people\s*carrier)\b/.test(s)) return { v: '8seater', caps: ['8 Seater'], passengers: '7+' };
  if (s === '5' || /\b(wheelchair|accessible|disabled|wav)\b/.test(s)) return { v: 'wheelchair', caps: ['Wheelchair'], passengers: '1-4' };
  return null;
}
function matchYesNo(s) {
  if (s === '1' || /\b(yes|y|yeah|yep|confirm|correct|ok|okay|right)\b/.test(s)) return 'yes';
  if (s === '2' || /\b(no|n|nope|wrong|retype|change|edit)\b/.test(s)) return 'retype';
  if (s === '3' || /\b(cancel|stop|abort|nevermind)\b/.test(s)) return 'cancel';
  return null;
}

// Global escape hatches at any state
if (/^(restart|reset|start over|cancel)$/i.test(reply)) {
  session.step = 'welcome';
  session.intent = '';
  session.status = 'open';
  return [{ json: session }];
}
if (/^(help|menu|options)$/i.test(reply)) {
  session.step = 'welcome';
  return [{ json: session }];
}
// Guard: if we're mid-airport-flow, ignore replies to old welcome/intent buttons
const airportSteps = new Set([
  'airport_pickup_ask_arrival_date',
  'airport_pickup_choose_airport',
  'airport_pickup_choose_terminal',
  'airport_pickup_ask_flight',
  'airport_pickup_lookup_flight',
  'airport_pickup_choose_buffer'
]);
if (airportSteps.has(session.step) && /^(book|quote|manage)$/.test(reply)) {
  // User tapped a stale welcome button — re-send the prompt for the current step
  return [{ json: session }];   // step unchanged → Route_By_Step re-sends current prompt
}

// State transitions
switch (session.step) {
  case 'welcome': {
  const it = matchIntent(reply);
  if (it === 'book')  { session.intent = 'book';  session.step = 'awaiting_time_mode'; }
  else if (it === 'quote') { session.intent = 'quote'; session.step = 'awaiting_time_mode'; }
  else if (it === 'manage') {
    // Skip the phone-confirm prompt — we already know the user's WhatsApp number.
    session.intent       = 'manage_booking';
    session.lookupPhone  = session.phone;
    session.fetchDetails = false;
    session.step         = 'manage_fetching';
  }
  break;
}
case 'awaiting_intent': {
  const it = matchIntent(reply);
  if (it === 'book')  { session.intent = 'book';  session.step = 'awaiting_time_mode'; }
  else if (it === 'quote') { session.intent = 'quote'; session.step = 'awaiting_time_mode'; }
  else if (it === 'manage') {
    session.intent       = 'manage_booking';
    session.lookupPhone  = session.phone;
    session.fetchDetails = false;
    session.step         = 'manage_fetching';
  }
  break;
}
  case 'awaiting_time_mode': {
    const tm = matchTimeMode(reply);
    if (tm === 'asap') { session.pickupTimeMode = 'asap'; session.pickupDateTime = ''; session.step = 'awaiting_pickup'; }
    else if (tm === 'later') { session.pickupTimeMode = 'later'; session.step = 'awaiting_pickup_time'; }
    else if (tm === 'airport') {
  session.pickupTimeMode = 'airport';
  session.intent = 'airport_pickup';
  session.airport = {};
  session.step = 'airport_pickup_ask_arrival_date'; // ← new entry point
    }
    break;
  }
    case 'airport_pickup_ask_arrival_date': {
  const raw = (reply || '').trim();
  const lc  = raw.toLowerCase().replace(/\s+/g, ' ');

  // Strip filler words so "27th of May", "the 27th of may", "on May 27th" all simplify
  const cleaned = lc
    .replace(/\b(the|on|of|please|for|this is|it[''']s|its)\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const MONTHS = {
    january:0, jan:0, february:1, feb:1, march:2, mar:2, april:3, apr:3,
    may:4, june:5, jun:5, july:6, jul:6, august:7, aug:7,
    september:8, sept:8, sep:8, october:9, oct:9, november:10, nov:10,
    december:11, dec:11
  };
  const WEEKDAYS = {
    sunday:0, sun:0, monday:1, mon:1, tuesday:2, tue:2, tues:2,
    wednesday:3, wed:3, weds:3, thursday:4, thu:4, thur:4, thurs:4,
    friday:5, fri:5, saturday:6, sat:6
  };
  const WORD_NUM = {
    one:1, two:2, three:3, four:4, five:5, six:6, seven:7, eight:8, nine:9, ten:10,
    eleven:11, twelve:12, thirteen:13, fourteen:14, fifteen:15,
    twenty:20, thirty:30, a:1, an:1
  };

  function mkUtcDate(y, m, d) { return new Date(Date.UTC(y, m, d, 12, 0, 0)); }
  function todayUtc() {
    const n = new Date();
    return mkUtcDate(n.getUTCFullYear(), n.getUTCMonth(), n.getUTCDate());
  }
  function addDays(d, n) { return new Date(d.getTime() + n * 86400000); }
  function ukDate(d) {
    return d.toLocaleDateString('en-GB', { timeZone:'UTC', day:'2-digit', month:'2-digit', year:'numeric' });
  }
  function bumpFutureIfYearMissing(yearProvided, candidate) {
    if (!yearProvided && candidate < todayUtc()) candidate.setUTCFullYear(candidate.getUTCFullYear() + 1);
    return candidate;
  }

  let arrivalDate = null;
  let m;

  // ---- 1. Plain relatives ----
  if (!arrivalDate && /^today\b/.test(cleaned))                       arrivalDate = todayUtc();
