  const parts = {};
  fmt.formatToParts(d).forEach(p => parts[p.type] = p.value);
  const londonAsUtc = Date.UTC(+parts.year, +parts.month - 1, +parts.day,
                               +parts.hour, +parts.minute, +parts.second);
  return Math.round((londonAsUtc - d.getTime()) / 60000);
};

const fmtOffset = (min) => {
  const sign = min >= 0 ? '+' : '-';
  const a = Math.abs(min);
  return `${sign}${String(Math.floor(a / 60)).padStart(2, '0')}:${String(a % 60).padStart(2, '0')}`;
};

const nowInLondonParts = () => {
  const n = new Date();
  const fmt = new Intl.DateTimeFormat('en-GB', {
    timeZone: OPERATOR_TZ, hour12: false,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit', weekday: 'long'
  });
  const p = {};
  fmt.formatToParts(n).forEach(x => p[x.type] = x.value);
  return {
    year: +p.year, month: +p.month, day: +p.day,
    hour: +p.hour, minute: +p.minute, second: +p.second,
    weekdayName: p.weekday.toLowerCase()
  };
};

const londonToUtcMs = (y, m, d, h, mn) => {
  let guess = Date.UTC(y, m, d, h, mn);
  for (let i = 0; i < 2; i++) {
    const off = getLondonOffsetMinutes(new Date(guess));
    guess = Date.UTC(y, m, d, h, mn) - off * 60000;
  }
  return guess;
};

// ---------- Working state ----------
const now = nowInLondonParts();
const work = { y: now.year, m: now.month - 1, d: now.day, h: now.hour, min: now.minute };
const todayMs = Date.UTC(now.year, now.month - 1, now.day);
let explicitDate = false;
let explicitTime = false;

// ---------- Text normalisation ----------
let text = rawInput
  .replace(/\b(at|for|on|by|around|about|approximately|roughly)\b/g, ' ')
  .replace(/[,]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const DAYS = {
  sunday: 0, sun: 0, monday: 1, mon: 1, tuesday: 2, tue: 2, tues: 2,
  wednesday: 3, wed: 3, weds: 3, thursday: 4, thu: 4, thur: 4, thurs: 4,
  friday: 5, fri: 5, saturday: 6, sat: 6
};
const MONTHS = {
  january: 0, jan: 0, february: 1, feb: 1, march: 2, mar: 2,
  april: 3, apr: 3, may: 4, june: 5, jun: 5, july: 6, jul: 6,
  august: 7, aug: 7, september: 8, sept: 8, sep: 8,
  october: 9, oct: 9, november: 10, nov: 10, december: 11, dec: 11
};
const todayDow = DAYS[now.weekdayName];

const applyDayOffset = (offsetDays) => {
  const d = new Date(Date.UTC(work.y, work.m, work.d) + offsetDays * 86400000);
  work.y = d.getUTCFullYear();
  work.m = d.getUTCMonth();
  work.d = d.getUTCDate();
  explicitDate = true;
};

// "today" / "tonight"
if (!explicitDate && /\b(today|tonight)\b/.test(text)) {
  explicitDate = true;
}
// "day after tomorrow"
if (!explicitDate && /\bday after tomorrow\b/.test(text)) applyDayOffset(2);
// "tomorrow"
if (!explicitDate && /\btomorrow\b/.test(text)) applyDayOffset(1);

// "in N days"
if (!explicitDate) {
  const m = text.match(/^in\s+(\d{1,3})\s+days?\b/);
  if (m) applyDayOffset(parseInt(m[1], 10));
}

// Weekday matching
if (!explicitDate) {
  const nextDay  = text.match(/\bnext\s+(sunday|monday|tuesday|wednesday|thursday|friday|saturday|sun|mon|tue|tues|wed|weds|thu|thur|thurs|fri|sat)\b/);
  const thisDay  = text.match(/\bthis\s+(sunday|monday|tuesday|wednesday|thursday|friday|saturday|sun|mon|tue|tues|wed|weds|thu|thur|thurs|fri|sat)\b/);
  const plainDay = text.match(/\b(sunday|monday|tuesday|wednesday|thursday|friday|saturday)\b/);
  let target = null, kind = null;
  if (nextDay)       { target = DAYS[nextDay[1]];  kind = 'next';  }
  else if (thisDay)  { target = DAYS[thisDay[1]];  kind = 'this';  }
  else if (plainDay) { target = DAYS[plainDay[1]]; kind = 'plain'; }
  if (target !== null) {
    let offset = (target - todayDow + 7) % 7;
    if (kind === 'next'  && offset === 0) offset = 7;
    if (kind === 'next'  && offset <  7) offset += 7;
    if (kind === 'plain' && offset === 0) offset = 7;
    applyDayOffset(offset);
  }
}

// Specific dates: "27 May", "27th of May", "May 27", "27/05/2026", "2026-05-27"
if (!explicitDate) {
  const dmText = text.match(/\b(\d{1,2})(?:st|nd|rd|th)?\s+(?:of\s+)?(january|february|march|april|may|june|july|august|september|sept|sep|october|november|december|jan|feb|mar|apr|jun|jul|aug|oct|nov|dec)(?:\s+(\d{2,4}))?\b/);
  const mdText = text.match(/\b(january|february|march|april|may|june|july|august|september|sept|sep|october|november|december|jan|feb|mar|apr|jun|jul|aug|oct|nov|dec)\s+(\d{1,2})(?:st|nd|rd|th)?(?:\s+(\d{2,4}))?\b/);
  const slash  = text.match(/\b(\d{1,2})[\/\-.](\d{1,2})(?:[\/\-.](\d{2,4}))?\b/);
  const iso    = text.match(/\b(\d{4})-(\d{1,2})-(\d{1,2})\b/);
  let dy = null, mo = null, yr = null, yearProvided = false;
  if (dmText)      { dy = +dmText[1]; mo = MONTHS[dmText[2]]; yr = dmText[3] ? +dmText[3] : now.year; yearProvided = !!dmText[3]; }
  else if (mdText) { mo = MONTHS[mdText[1]]; dy = +mdText[2]; yr = mdText[3] ? +mdText[3] : now.year; yearProvided = !!mdText[3]; }
  else if (iso)    { yr = +iso[1]; mo = +iso[2] - 1; dy = +iso[3]; yearProvided = true; }
  else if (slash)  { dy = +slash[1]; mo = +slash[2] - 1; yr = slash[3] ? +slash[3] : now.year; yearProvided = !!slash[3]; }
  if (dy !== null && mo !== null && yr !== null) {
    if (yr < 100) yr += 2000;
    work.y = yr; work.m = mo; work.d = dy;
    explicitDate = true;
    if (!yearProvided) {
      const candidateMs = Date.UTC(work.y, work.m, work.d);
      if (candidateMs < todayMs) work.y += 1;
    }
  }
}

// ---------- Time parsing ----------
let hour = null, minute = 0, isPM = null;

if (/\b(noon|midday)\b/.test(text)) { hour = 12; minute = 0; explicitTime = true; }
if (/\bmidnight\b/.test(text))      { hour = 0;  minute = 0; explicitTime = true; }

if (hour === null) {
  const m = text.match(/\b(\d{1,2}):(\d{2})\s*(am|pm|a\.?m\.?|p\.?m\.?)?\b/);
  if (m) {
    hour = +m[1]; minute = +m[2];
    if (m[3]) isPM = m[3].toLowerCase().startsWith('p');
    explicitTime = true;
  }
}
if (hour === null) {
  const m = text.match(/\b(\d{1,2})\s*(am|pm|a\.?m\.?|p\.?m\.?)\b/);
  if (m) {
    hour = +m[1]; minute = 0;
    isPM = m[2].toLowerCase().startsWith('p');
    explicitTime = true;
  }
}
if (hour === null) {
  const m = text.match(/\b(\d{1,2})\s*o[''']?\s*clock\b/);
  if (m) {
    hour = +m[1]; minute = 0;
    if (/\b(evening|night|tonight|afternoon)\b/.test(text)) isPM = true;
    else if (/\b(morning)\b/.test(text)) isPM = false;
    explicitTime = true;
  }
}

if (hour !== null) {
  if (isPM === true && hour < 12) hour += 12;
  else if (isPM === false && hour === 12) hour = 0;
  work.h = hour; work.min = minute;
}

if (explicitDate && !explicitTime) { work.h = 12; work.min = 0; }

// ---------- Compute UTC + offset, with auto-bump if past ----------
let utcMs = londonToUtcMs(work.y, work.m, work.d, work.h, work.min);

if (!explicitDate && utcMs <= Date.now()) {
  // Push one day forward when no date was specified and the time has already passed
  const tomorrow = new Date(Date.UTC(work.y, work.m, work.d) + 86400000);
  work.y = tomorrow.getUTCFullYear();
  work.m = tomorrow.getUTCMonth();
  work.d = tomorrow.getUTCDate();
  utcMs = londonToUtcMs(work.y, work.m, work.d, work.h, work.min);
}

const utcDate = new Date(utcMs);
const offsetMin = getLondonOffsetMinutes(utcDate);
const localMs = utcMs + offsetMin * 60000;
const local = new Date(localMs);

const pad = (n) => String(n).padStart(2, '0');
const localIso =
  `${local.getUTCFullYear()}-${pad(local.getUTCMonth() + 1)}-${pad(local.getUTCDate())}` +
  `T${pad(local.getUTCHours())}:${pad(local.getUTCMinutes())}:00` +
  `${fmtOffset(offsetMin)}`;
const utcIso = utcDate.toISOString().replace(/\.\d{3}Z$/, '.000Z');

session.pickupDateTime    = localIso;   // London local with +01:00 / +00:00
session.pickupDateTimeUtc = utcIso;     // UTC with .000Z
session.pickupDueTime     = utcIso;     // Autocab field — same as Utc
session.pickupDueTimeUtc  = utcIso;     // Autocab field
session.rawTimeInput      = '';
return [{ json: session }];

