// =====================================================================
// Pick_Best_Flight — tolerant of HTTP wrappers, response shapes,
// field-name drift, IATA codeshare, and missing data.
// =====================================================================

// Snapshot the outgoing request so debugging future failures is one click
const reqSnapshot = {
  searchTextSent: $('Apply_Voice_Slots').first().json.airport.flightNumber,
  searchTimeSent: new Date().toISOString(),
  companyIdSent: 1
};

// --- 0. Handle "Include Response Headers and Status" wrapper ---
const httpResp = $json;
const raw = httpResp && httpResp.body !== undefined ? httpResp.body : httpResp;

const session  = $('Apply_Voice_Slots').first().json;
const wantCode = (session.airport && session.airport.code) || '';
const wantFn   = (session.airport && session.airport.flightNumber || '').toUpperCase().replace(/\s+/g, '');

// --- 1. Unwrap response into a flat array of flight objects ---
let flights = [];
if (Array.isArray(raw)) {
  flights = raw;
} else if (raw && typeof raw === 'object') {
  flights =
    raw.flights ||
    raw.data ||
    raw.results ||
    raw.items ||
    raw.searchResults ||
    raw.value ||
    [];
  if (!Array.isArray(flights)) {
    flights = (raw.airlineCode || raw.flightNumber) ? [raw] : [];
  }
}

// --- 2. Normalise field names ---
function pick(obj, ...keys) {
  for (const k of keys) {
    if (obj && obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
  }
  return undefined;
}
function normalise(f) {
  return {
    airlineCode:        pick(f, 'airlineCode', 'airlineIata', 'iataAirlineCode', 'carrierCode'),
    flightNumber:       pick(f, 'flightNumber', 'flightNo', 'number'),
    arrivalAirport:     pick(f, 'arrivalAirport', 'arrivalAirportName', 'destinationAirport'),
    arrivalAirportCode: pick(f, 'arrivalAirportCode', 'arrivalIata', 'destinationAirportCode', 'arrivalIataCode'),
    arrivalTerminal:    pick(f, 'arrivalTerminal', 'terminal'),
    arrivalTime:        pick(f, 'arrivalTime', 'arrivalTimeUtc', 'scheduledArrivalUtc', 'estimatedArrivalUtc', 'scheduledArrival'),
    summary:            pick(f, 'summary', 'description', 'displayName'),
    _raw:               f
  };
}
const normFlights = flights.map(normalise);

// --- 3. Match best flight ---
const matchesAirport = f => (f.arrivalAirportCode || '').toUpperCase() === wantCode.toUpperCase();
const matchesFlight  = f => {
  const code = (f.airlineCode || '').toUpperCase();
  const num  = String(f.flightNumber || '').replace(/^0+/, '');   // strip leading zeros
  return (code + num) === wantFn || (code + num.padStart(3, '0')) === wantFn;
};

let exact = normFlights.find(f => matchesAirport(f) && matchesFlight(f));
if (!exact) exact = normFlights.find(matchesAirport);
const fallback = normFlights[0];

// --- 4. Decide outcome ---
if (!exact && !fallback) {
  session.airport.error     = 'no_flight_found';
  session.airport.candidate = null;
  session.airport.lookupDebug = {
    request:    reqSnapshot,
    statusCode: httpResp && httpResp.statusCode || null,
    rawType:    Array.isArray(raw) ? 'array' : typeof raw,
    rawKeys:    (raw && typeof raw === 'object' && !Array.isArray(raw)) ? Object.keys(raw) : null,
    rawCount:   Array.isArray(raw) ? raw.length : (Array.isArray(flights) ? flights.length : 0),
    errMsg: (
  (raw && raw.errors && raw.errors[0] && (raw.errors[0].detail || raw.errors[0].title)) ||
  (raw && raw.message) ||
  (raw && raw.error) ||
  null
)
  };
  session.step = 'airport_pickup_ask_flight';
  return [{ json: session }];
}

if (!exact && fallback) {
  session.airport.error      = 'wrong_airport';
  session.airport.candidate  = fallback._raw;
  session.airport.lookupDebug = {
    request:    reqSnapshot,
    statusCode: httpResp && httpResp.statusCode || null,
    rawCount:   normFlights.length
  };
  session.step = 'airport_pickup_ask_flight';
  return [{ json: session }];
}

// --- 5. Happy path ---
session.airport.error              = null;
session.airport.candidate          = null;
session.airport.flightNumber       = `${exact.airlineCode || ''}${exact.flightNumber || ''}`;
session.airport.arrivalAirport     = exact.arrivalAirport;
session.airport.arrivalAirportCode = exact.arrivalAirportCode;
session.airport.arrivalTerminal    = exact.arrivalTerminal || session.airport.terminal;
session.airport.arrivalTimeUtc     = exact.arrivalTime;
session.airport.flightSummary      = exact.summary ||
  `${exact.airlineCode}${exact.flightNumber} arriving ${exact.arrivalAirportCode}${exact.arrivalTerminal ? ' T' + exact.arrivalTerminal : ''} at ${exact.arrivalTime}`;
session.airport.flightObject       = exact._raw;
session.airport.lookupDebug        = { request: reqSnapshot, statusCode: httpResp && httpResp.statusCode || null, rawCount: normFlights.length };
session.step = 'airport_pickup_choose_buffer';
return [{ json: session }];

