parameters.jsCode:
const session = $('Pick_Best_Flight').first().json;
const a = session.airport || {};

const AIRPORT_NAME = {
  LHR: "Heathrow Airport",
  LGW: "Gatwick Airport",
  STN: "Stansted Airport",
  LTN: "Luton Airport",
  LCY: "London City Airport"
};

const TERMINAL_TEXT = {
  LHR: t => t ? `Terminal ${t}` : "",
  LGW: t => t === 'N' ? "North Terminal" : t === 'S' ? "South Terminal" : "",
  STN: () => "",
  LTN: () => "",
  LCY: () => ""
};

// Prefer the terminal Autocab returned from the flight API; fall back to user's choice
const terminal = a.arrivalTerminal || a.terminal || null;
const name = AIRPORT_NAME[a.code];
const term = TERMINAL_TEXT[a.code](terminal);

const text = [name, term].filter(Boolean).join(" ");   // e.g. "Heathrow Airport Terminal 5"

return [{ json: { ...$json, airport: { ...a, addressQuery: text } } }];

const list = Array.isArray($json) ? $json : [];
const session = $('Update_State_From_Reply').first().json;
const q = (session.airport.addressQuery || '').toLowerCase();

// Prefer a candidate whose text mentions both "airport" and (if present) the terminal phrase
const term = q.includes('terminal') ? q.match(/(north|south|terminal [1-5])/)?.[0] : null;
const score = (c) => {
  const a = (c.address || c.fullAddress || '').toLowerCase();
  let s = 0;
  if (a.includes('airport')) s += 2;
  if (term && a.includes(term)) s += 3;
  if (a.includes(q.split(' ')[0])) s += 1; // "heathrow", "gatwick", etc.
  return s;
};

const best = list.slice().sort((a, b) => score(b) - score(a))[0];

if (!best || !best.placeID) {
  // Fallback: keep going with a free-text pickup so booking still succeeds
  session.airport.pickupAddress = null;
  session.airport.placeId = null;
  return [{ json: session }];
}

session.airport.placeId = best.placeID;
session.airport.pickupAddressText = best.address || best.fullAddress;
return [{ json: session }];

// =====================================================================
// Build_Airport_Pickup_Address
// Produces a quote-ready Autocab address for the airport pickup leg.
//
// Strategy:
//   1. If Autocab_Get_Address_By_PlaceId resolved upstream, trust it.
//   2. Otherwise use the operator's real zone data (LHR has per-terminal
//      zones), and embed the canonical coordinate + zone object so the
//      quote payload validates and Autocab prices correctly.
//
// Zone IDs verified from GET /booking/v1/zones?companyId=1.
// =====================================================================

const session = $('Build_Pickup_Address_Query').first().json;
const a = session.airport || {};
const detail = $json || {};   // upstream: Autocab_Get_Address_By_PlaceId

// --- Heathrow terminal → zone lookup ---
// T1/T2/T3 share one zone, T4 has its own, T5 has its own.
function lhrZoneForTerminal(term) {
  const t = String(term || '').trim().toUpperCase();
  if (t === '4') {
    return {
      id: 37, mdtZoneId: 38,
      name: 'LHR T4', descriptor: 'LHR T4',
      coord: { latitude: 51.459098888888889, longitude: -0.44080388888888888, isEmpty: false },
      text: 'Heathrow Airport Terminal 4',
      town: 'Hounslow', postCode: 'TW6 3XA'
    };
  }
  if (t === '5') {
    return {
      id: 39, mdtZoneId: 40,
      name: 'LHR T5', descriptor: 'LHR T5',
      coord: { latitude: 51.466025833333333, longitude: -0.46129083333333332, isEmpty: false },
      text: 'Heathrow Airport Terminal 5',
      town: 'Hounslow', postCode: 'TW6 2GA'
    };
  }
  // Default for T1, T2, T3, or missing
  const label = (t === '1' || t === '2' || t === '3') ? `Terminal ${t}` : 'Terminals 2 & 3';
  return {
    id: 38, mdtZoneId: 39,
    name: 'LHR T123', descriptor: 'LHR T123',
    coord: { latitude: 51.473405833333331, longitude: -0.4403327777777778, isEmpty: false },
    text: `Heathrow Airport ${label}`,
    town: 'Hounslow', postCode: 'TW6 1QG'
  };
}

// --- Non-Heathrow airports (single zone each) ---
const AIRPORT_ZONES = {
  LGW: {
    id: 57, mdtZoneId: 59,
    name: 'Gatwick', descriptor: 'Gatwick',
    coord: { latitude: 51.157506944444442, longitude: -0.17620083333333333, isEmpty: false },
    fullName: 'Gatwick Airport',
    town: 'Gatwick', postCode: 'RH6 0NP'
  },
  STN: {
    id: 89, mdtZoneId: 91,
    name: 'Stanstead', descriptor: 'Stanstead',
    coord: { latitude: 52.002783888888892, longitude: 0.15650583333333334, isEmpty: false },
    fullName: 'Stansted Airport',
    town: 'Stansted', postCode: 'CM24 1QW'
  },
  LTN: {
    id: 87, mdtZoneId: 89,
    name: 'Luton', descriptor: 'Luton',
    coord: { latitude: 51.76580388888889, longitude: -0.37231888888888887, isEmpty: false },
    fullName: 'Luton Airport',
    town: 'Luton', postCode: 'LU2 9LY'
  },
  LCY: {
    id: 185, mdtZoneId: 160,
    name: 'London City Airport', descriptor: 'LCY',
    coord: { latitude: 51.506830555555553, longitude: 0.039749444444444441, isEmpty: false },
    fullName: 'London City Airport',
    town: 'London', postCode: 'E16 2PX'
  }
};

// --- Build the address suffix shown to dispatchers/drivers ---
function buildText(code, term) {
  if (code === 'LHR') {
    return lhrZoneForTerminal(term).text;
  }
  const ap = AIRPORT_ZONES[code];
  if (!ap) return (a.name || 'Airport') + (term ? ` – Terminal ${term}` : '');
  if (code === 'LGW') {
    const suffix = term === 'N' ? ' North Terminal' : term === 'S' ? ' South Terminal' : '';
    return ap.fullName + suffix;
  }
  return ap.fullName;
}

// --- 1. Prefer Autocab-resolved address if upstream lookup actually succeeded ---
const upstreamOk =
     detail
  && detail.text
  && detail.coordinate
  && detail.coordinate.latitude !== undefined
  && detail.coordinate.latitude !== null
  && (detail.zoneId !== undefined || detail.zone);

let pickupAddress;

if (upstreamOk) {
  pickupAddress = {
    source:           detail.source,
    id:               detail.id,
    isCustom:         detail.isCustom === true,
    searchTypeLetter: detail.searchTypeLetter,
    zone:             detail.zone,
    zoneId:           detail.zoneId !== undefined ? detail.zoneId : (detail.zone && detail.zone.id),
    bookingPriority:  detail.bookingPriority || 0,
    text:             detail.text,
    coordinate:       detail.coordinate,
    house:            detail.house || '',
    street:           detail.street || '',
    town:             detail.town || '',
    postCode:         detail.postCode || '',
    note: a.arrivalTerminal
      ? `Flight ${a.flightNumber} – Terminal ${a.arrivalTerminal}`
      : `Flight ${a.flightNumber}`
  };
} else {
  // --- 2. Use the operator's real zone data ---
  const code = a.code;
  const term = a.arrivalTerminal || a.terminal || null;
  let z;

  if (code === 'LHR') {
    z = lhrZoneForTerminal(term);
  } else if (AIRPORT_ZONES[code]) {
    z = AIRPORT_ZONES[code];
  }

  if (z) {
    const text = buildText(code, term);
    pickupAddress = {
      source:           'Operator',
      id:               -1,
      isCustom:         false,
      searchTypeLetter: 'Z',
      zone: {
        id:         z.id,
        name:       z.name,
        descriptor: z.descriptor,
        mdtZoneId:  z.mdtZoneId
      },
      zoneId:           z.id,
      bookingPriority:  0,
      text:             text,
      coordinate:       z.coord,
      house:            '',
      street:           text,
      town:             z.town,
      postCode:         z.postCode,
      note: term
        ? `Flight ${a.flightNumber} – Terminal ${term}`
        : `Flight ${a.flightNumber}`
    };
  } else {
    // --- 3. Truly unknown airport — last-ditch custom address ---
    pickupAddress = {
      isCustom: true,
      text:     (a.name || 'Airport') + (a.arrivalTerminal ? ` – Terminal ${a.arrivalTerminal}` : ''),
      note:     `Flight ${a.flightNumber}`
    };
  }
}

// --- 4. Persist into session and advance the state machine ---
session.pickupAddressJson = JSON.stringify(pickupAddress);
session.pickupText        = pickupAddress.text;
session.pickupTimeMode    = 'later';                       // scheduled job
session.pickupDateTime    = a.pickupAtUtc || null;         // arrival + buffer

// CRITICAL: set step to a case that's actually handled
session.step = 'airport_pickup_choose_buffer';

return [{ json: session }];

