const reply = ($('Extract_WhatsApp_Data').item.json.messageText || '').trim();
const raw = $('Get_Session').item.json;
const session = raw.session || raw;

if (/^(yes|y|phone_confirm_yes)$/i.test(reply)) {
  session.lookupPhone = $('Extract_WhatsApp_Data').item.json.phone;
} else {
  session.lookupPhone = reply.replace(/[^\d+]/g, '');
}
session.step = 'manage_fetching';
return [{ json: { session } }];

const session = $json || $('Get_Session').item.json;
const phone   = session.lookupPhone || session.phone;

if (!phone) throw new Error('Build_Search_Payload: no phone to look up.');

const now  = new Date();
const from = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 1).toISOString();   // 1 day back (covers in-progress trips)
const to   = new Date(now.getTime() + 1000 * 60 * 60 * 24 * 60).toISOString();  // 60 days ahead

return [{ json: {
  ...session,
  lookupPhone: phone,
  payload: {
    from, to,
    telephoneNumber: phone,
    exactMatch: false,
    ignorePostcode: true,
    ignoreTown: true,
    // Live booking types only — no Completed / Cancelled / NoJob
    types: ['Active', 'Advanced', 'Mobile', 'Dispatched', 'ExchangedActive', 'ExchangedMobile']
  }
}}];

const bookings = $json.bookings || [];
const session  = $('Build_Search_Payload').first().json;

const LIVE_TYPES = ['Active','Advanced','Mobile','Dispatched','ExchangedActive','ExchangedMobile'];
const isCurrent = b => LIVE_TYPES.includes(b.bookingType);

const ordered = bookings
  .filter(isCurrent)
  .sort((a, b) => new Date(a.pickupDueTime) - new Date(b.pickupDueTime))
  .slice(0, 10);

const TZ = 'Europe/London';
const fmtDate = d => new Date(d).toLocaleDateString('en-GB', { timeZone: TZ });
const fmtTime = d => new Date(d).toLocaleTimeString('en-GB', { timeZone: TZ, hour: '2-digit', minute: '2-digit' });

if (ordered.length === 0) {
  return [{ json: {
    ...session,
    step: 'awaiting_intent',
    nextAction: 'send_text',
    managedBookingsJson: '[]',
    interactive: null,
    text: `No active bookings found for ${session.lookupPhone || session.phone}.\nReply MENU to go back.`
  }}];
}

const rows = ordered.map((b, i) => ({
  id: `BK_${b.id}`,
  title: `${i + 1}. ${fmtDate(b.pickupDueTime)} ${fmtTime(b.pickupDueTime)}`.slice(0, 24),
  description: `${(b.pickup?.address?.text || '').split(',')[0]} → ${(b.destination?.address?.text || '').split(',')[0]} · £${b.pricing?.price ?? '-'}`.slice(0, 72)
}));

return [{ json: {
  ...session,
  step: 'manage_list_displayed',
  nextAction: 'send_list',
  managedBookingsJson: JSON.stringify(
    ordered.map(b => ({ id: b.id, isCurrent: true, rowVersion: b.rowVersion }))
  ),
  selectedBookingId: '',
  selectedBookingIsCurrent: '',
  interactive: {
    type: 'list',
    header: { type: 'text', text: 'Your active bookings' },
    body:   { text: `Found ${ordered.length} active booking(s). Pick one to manage.` },
    footer: { text: 'Or type MENU to go back' },
    action: { button: 'Select booking', sections: [{ title: 'Active bookings', rows }] }
  }
}}];

