const reply   = ($('Extract_WhatsApp_Data').item.json.messageText || '').trim();
const session = $('Get_Session').item.json;
const list    = JSON.parse(session.managedBookingsJson || '[]');

// ── Escape hatch ─────────────────────────────────────────────
if (/^menu$/i.test(reply)) {
  return [{ json: {
    ...session,
    step: 'awaiting_intent',
    nextAction: 'send_text',
    interactive: null,
    text: 'Back to main menu. Reply 1, 2, or 3.'
  }}];
}

// ── Resolve which booking the user picked ────────────────────
let idx = -1;
if (reply.startsWith('BK_')) {
  idx = list.findIndex(b => String(b.id) === reply.slice(3));
} else {
  const n = parseInt(reply, 10);
  if (!isNaN(n)) idx = n - 1;
}

if (idx < 0 || idx >= list.length) {
  return [{ json: {
    ...session,
    step: 'manage_list_displayed',
    nextAction: 'send_text',
    interactive: null,
    text: 'Please tap a booking from the list, or type MENU to go back.'
  }}];
}

// ── Valid selection → hand off to the details fetcher ────────
const sel = list[idx];

return [{ json: {
  ...session,
  step: 'manage_fetching',
  nextAction: 'send_booking_details',
  selectedBookingId: String(sel.id),
  selectedBookingIsCurrent: sel.isCurrent ? 'true' : 'false',
  selectedBookingRowVersion: String(sel.rowVersion || ''),
  fetchDetails: true,
  interactive: null,
  text: ''
}}];

