const reply   = ($('Extract_WhatsApp_Data').item.json.messageText || '').trim();
const session = $('Get_Session').item.json;

if (/^back$/i.test(reply)) {
  return [{ json: {
    ...session,
    step: 'manage_action_menu',
    nextAction: 'send_text',
    interactive: null,
    text: 'Cancelled. Back to action menu.'
  }}];
}

const m = reply.match(/^(TIME|PICKUP|DEST|NAME|NOTE)\s+(.+)$/i);
if (!m) {
  return [{ json: {
    ...session,
    step: session.step,
    nextAction: 'send_text',
    interactive: null,
    text: 'Bad format. Try: TIME 28/05/2026 14:30'
  }}];
}

return [{ json: {
  ...session,
  modifyField: m[1].toUpperCase(),
  modifyValue: m[2].trim(),
  fetchDetails: true
}}];

const current = $json;
const session = $('Get_Session').first().json;
const pending = JSON.parse(session.pendingModifyJson || '{}');

// Deep-clone the booking we just fetched so we can mutate safely
const updated = JSON.parse(JSON.stringify(current));

// ── Pickup time: "DD/MM/YYYY HH:MM" interpreted in Europe/London, returned as UTC ISO
if (pending.pickupDueTime) {
  updated.pickupDueTime    = pending.pickupDueTime;
  updated.pickupDueTimeUtc = pending.pickupDueTime;
}

if (pending.name)       updated.name       = pending.name;
if (pending.driverNote) {
  updated.driverNote = pending.driverNote;          // root field (used by Autocab UI)
  updated.pickup = updated.pickup || {};
  updated.pickup.note = pending.driverNote;          // where create flow puts it
}
if (pending.vehicleType) {
  updated.vehicleConstraints = updated.vehicleConstraints || {};
  updated.vehicleConstraints.vehicleKind = pending.vehicleType;
}

// Autocab GET does NOT return `id` at root — pull the booking id from session
const bookingId = session.selectedBookingId || session.lastBookingId || '';

return [{ json: {
  bookingId,
  rowVersion: current.rowVersion,
  booking: updated,
  session
}}];

const reply   = ($('Extract_WhatsApp_Data').item.json.messageText || '').trim();
