// ── Helpers ────────────────────────────────────────────────────────
const TZ = 'Europe/London';
const fmtDate = d => new Date(d).toLocaleDateString('en-GB', { timeZone: TZ });
const fmtTime = d => new Date(d).toLocaleTimeString('en-GB', { timeZone: TZ, hour: '2-digit', minute: '2-digit' });

// Map Autocab capability tags to human vehicle labels
const VEHICLE_LABELS = {
  saloon:     '🚕 Saloon (standard)',
  estate:     '🚗 Estate',
  mpv:        '🚙 6-seater MPV',
  '6 seater': '🚙 6-seater MPV',
  '8seater':  '🚐 8-seater',
  '8 seater': '🚐 8-seater',
  wheelchair: '♿ Wheelchair WAV',
};

const vehicleFromCaps = (caps = [], constraints = {}, refs = {}) => {
  // Prefer our own stamped reference if present (booked through this bot)
  const stamped = (refs?.yourReference2 || '').toLowerCase().trim();
  if (stamped && VEHICLE_LABELS[stamped]) return VEHICLE_LABELS[stamped];

  // Otherwise inspect capabilities — handle string, object, or numeric formats
  const names = (caps || []).map(c => {
    if (c == null) return '';
    if (typeof c === 'string') return c.toLowerCase();
    if (typeof c === 'object') return String(c.name || c.descriptor || '').toLowerCase();
    return '';
  });
  const has = (s) => names.some(n => n.includes(s));

  if (has('wheelchair')) return VEHICLE_LABELS.wheelchair;
  if (has('8 seat') || has('eight seat')) return VEHICLE_LABELS['8seater'];
  if (has('6 seat') || has('six seat'))   return VEHICLE_LABELS.mpv;
  if (has('estate'))    return VEHICLE_LABELS.estate;

  return b.vehicle?.type
      || constraints?.vehicleKind
      || VEHICLE_LABELS.saloon;
};

// Status pill
const STATUS_EMOJI = {
  Active: '🟢', Advanced: '🗓️', Mobile: '🛺', Dispatched: '🚖',
  ExchangedActive: '🔄', ExchangedMobile: '🔄',
  Completed: '✅', Cancelled: '❌', NoJob: '⚪'
};
const statusEmoji = STATUS_EMOJI[b.bookingType] || '📌';

// ── Field values ───────────────────────────────────────────────────
const isCurrent = ['Active','Advanced','Mobile','Dispatched','ExchangedActive','ExchangedMobile'].includes(b.bookingType);

const datePart  = b.pickupDueTime ? fmtDate(b.pickupDueTime) : '-';
const timePart  = b.pickupDueTime ? fmtTime(b.pickupDueTime) : '-';
const from      = b.pickup?.address?.text       || '-';
const to        = b.destination?.address?.text  || '-';
const name      = (b.name || '').trim()         || '-';
const phone     = b.telephoneNumber             || '-';
const passengers= b.passengers                  ?? 1;
const note = (
  b.driverNote ||
  b.pickup?.note ||
  b.destination?.note ||
  b.officeNote ||
  b.passengerInformation ||
  ''
).trim();
const vehicle = vehicleFromCaps(b.capabilities, b.vehicleConstraints, b.yourReferences);
const price     = b.pricing?.price != null ? `£${Number(b.pricing.price).toFixed(2)}` : '-';
const distance  = b.distance != null ? `${Number(b.distance).toFixed(1)} mi` : '';
const payment   = b.paymentMethod || b.paymentType || '';

// ── Build card body ────────────────────────────────────────────────
const lines = [];
lines.push(`📋 *Booking #${b.id}*`);
lines.push(`${statusEmoji} Status: ${b.bookingType}`);
lines.push('');
lines.push(`📅 Date: ${datePart}`);
lines.push(`🕒 Time: ${timePart} (London)`);
lines.push('');
lines.push(`📍 From: ${from}`);
lines.push(`🎯 To: ${to}`);
if (distance) lines.push(`📏 Distance: ${distance}`);
lines.push('');
lines.push(`👤 Passenger: ${name}`);
lines.push(`📞 Phone: ${phone}`);
lines.push(`👥 Passengers: ${passengers}`);
lines.push(`🚘 Vehicle: ${vehicle}`);
lines.push(`📝 Note: ${note ? note : '(note)'}`);
lines.push('');
lines.push(`💷 Price: ${price}${payment ? ` (${payment})` : ''}`);

const detailsText = lines.join('\n');

// ── Past bookings: plain text only (no actions allowed) ───────────
if (!isCurrent) {
  return [{ json: {
    ...session,
    step: 'manage_action_menu',
    nextAction: 'send_booking_details',
    selectedBookingId: String(b.id),
    selectedBookingRowVersion: String(b.rowVersion || ''),
    selectedBookingJson: JSON.stringify(b),
    interactive: null,
    text: `${detailsText}\n\nℹ️ This booking is in the past — no actions available.\nReply MENU to go back.`
  }}];
}

// ── Active bookings: interactive card with Modify / Cancel ───────
return [{ json: {
  ...session,
  step: 'manage_action_menu',
  nextAction: 'send_booking_details',
  selectedBookingId: String(b.id),
  selectedBookingRowVersion: String(b.rowVersion || ''),
  selectedBookingJson: JSON.stringify(b),
  text: detailsText,
  interactive: {
    type: 'button',
    header: { type: 'text', text: `Booking #${b.id}` },
    body:   { text: detailsText.slice(0, 1024) },
    footer: { text: 'Choose an action below' },
    action: { buttons: [
      { type: 'reply', reply: { id: `ACT_MODIFY_${b.id}`, title: '✏️ Modify' } },
      { type: 'reply', reply: { id: `ACT_CANCEL_${b.id}`, title: '❌ Cancel' } }
    ]}
  }
}}];

