                   v.luggage || (Number.isFinite(v.passengers) && v.passengers > 0));
if (!bookingIntent || !hasData) return [{ json: s }];

// Fresh one-shot: wipe stale data from a PREVIOUS booking so we only use this voice note.
s.pickupAddressJson = '';
s.destinationAddressJson = '';
s.vehicleType = '';
s.capabilitiesJson = '[]';
s.passengerCount = '';
s.pickupDateTime = ''; s.pickupDateTimeUtc = ''; s.pickupDueTime = ''; s.pickupDueTimeUtc = '';
s.pickupTimeMode = ''; s.rawTimeInput = '';
s.lastQuotePrice = ''; s.lastQuoteEta = '';
s.driverNote = '';
s.noteNextStep = '';
s.passengerName = '';   // never carry a previous booking's name (often a stale transcript) into a new one
s.airport = {};

const veh = chooseVehicle(v.vehicle, v.passengers, v.luggage);
if (veh) applyVehicle(s, veh, v.passengers);

if (v.passengerName) s.passengerName = v.passengerName;
if (v.note)          s.driverNote = v.note;
if (v.destination)   s.destinationText = v.destination;

const AIRPORT_RE = /\b(airport|heathrow|gatwick|stansted|stanstead|luton|city airport|lhr|lgw|stn|ltn|lcy|terminal\s*\d|terminal\s*[ns])\b/i;
const pickupIsAirport = AIRPORT_RE.test(v.pickup || '') || !!(v.airport && String(v.airport).trim()) || !!v.flightNumber;

if (pickupIsAirport) {
  const ap = resolveAirport((v.pickup || '') + ' ' + (v.airport || ''));
  const arr = parseDateLoose(v.whenText);
  s.intent = 'airport_pickup';
  s.pickupTimeMode = 'airport';
  s.airport.voicePrefill = true;
  if (arr) { s.airport.arrivalDate = arr.iso; s.airport.arrivalDateUk = arr.uk; s.airport.error = null; }
  if (ap) { s.airport.code = ap.code; s.airport.name = ap.name; }
  const term = normTerminal(v.terminal);
  if (term) s.airport.terminal = term;
  if (v.flightNumber) s.airport.flightNumber = String(v.flightNumber).toUpperCase().replace(/\s+/g, '');
  const needsTerminal = ap && (ap.code === 'LHR' || ap.code === 'LGW');
  const flightValid = s.airport.flightNumber && /^[A-Z0-9]{2,3}\d{1,4}$/.test(s.airport.flightNumber);
  if (!s.airport.arrivalDate)                       s.step = 'airport_pickup_ask_arrival_date';
  else if (!s.airport.code)                         s.step = 'airport_pickup_choose_airport';
  else if (flightValid)                             s.step = 'airport_pickup_lookup_flight';
  else if (needsTerminal && !s.airport.terminal)    s.step = 'airport_pickup_choose_terminal';
  else                                              s.step = 'airport_pickup_ask_flight';
  return [{ json: s }];
}

s.intent = (v.intent === 'quote') ? 'quote' : 'book';
if (v.whenText) { s.rawTimeInput = v.whenText; s.pickupTimeMode = 'later'; }
if (v.pickup) { s.pickupText = v.pickup; s.step = 'resolving_pickup_text'; }
else          { s.step = 'awaiting_pickup'; }
return [{ json: s }];

// Runs right after the webhook (message branch), BEFORE Extract_WhatsApp_Data.
// Flags voice notes and surfaces mediaId/phone so the voice subworkflow can run.
// Passes the original webhook payload through untouched for the non-voice path.
const j = $json || {};
const body = j.body ?? j;
let isVoice = false, mediaId = '', phone = '';
try {
  const msg = body.entry[0].changes[0].value.messages[0];
  phone = msg.from || '';
  if (msg.type === 'audio') { isVoice = true; mediaId = msg.audio && msg.audio.id ? msg.audio.id : ''; }
} catch (e) {}
return [{ json: { ...j, isVoice, mediaId, phone } }];

// Rewrites the original WhatsApp payload so the audio message looks like a normal
// text message carrying the transcript. Extract_WhatsApp_Data then parses it exactly
// like a typed message, so the whole downstream pipeline works unchanged.
const slots = $json || {};
const orig = $('Detect_Audio').first().json || {};
const body = JSON.parse(JSON.stringify(orig.body != null ? orig.body : orig));
try {
  const msg = body.entry[0].changes[0].value.messages[0];
  msg.type = 'text';
  msg.text = { body: (slots.transcript || '').toString() };
  delete msg.audio;
} catch (e) {}
return [{ json: { body, _voice: slots } }];
